import { Convrt } from "@convrt/sdk";

// Integrate with your framework's authenticated request handler.
export async function convertUpload(request: Request, userId: string | null) {
  if (!userId) return new Response("Unauthorized", { status: 401 });
  const baseUrl = process.env.CONVRT_API_URL;
  const apiKey = process.env.CONVRT_API_KEY;
  if (!baseUrl || !apiKey) return new Response("Service unavailable", { status: 503 });
  const reader = request.body?.getReader();
  if (!reader) return new Response("Missing body", { status: 400 });
  const chunks: Uint8Array<ArrayBuffer>[] = [];
  let size = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > 20 * 1024 * 1024) {
        await reader.cancel();
        return new Response("Upload too large", { status: 413 });
      }
      chunks.push(new Uint8Array(value));
    }
  } finally { reader.releaseLock(); }
  const body = await new Response(new Blob(chunks), {
    headers: { "Content-Type": request.headers.get("Content-Type") ?? "" },
  }).formData().catch(() => null);
  const file = body?.get("file");
  if (!(file instanceof File) || !/\.png$/i.test(file.name))
    return new Response("Choose a PNG file", { status: 400 });
  try {
    const client = new Convrt({ baseUrl, apiKey });
    const output = await client.convert(file, "webp", {}, { signal: request.signal });
    return new Response(output, { headers: {
      "Content-Type": "image/webp", "Cache-Control": "no-store",
      "Content-Disposition": 'attachment; filename="converted.webp"',
    } });
  } catch { return new Response("Conversion unavailable", { status: 502 }); }
}

const form = new FormData();
form.set("file", file);
const response = await fetch("/api/convert", { method: "POST", body: form });
if (!response.ok) throw new Error("Conversion failed");
const output = await response.blob();
